import io.github.diodeme.ji.ai.ModelRequest;
import io.github.diodeme.ji.ai.ModelStreamEvent;
import io.github.diodeme.ji.ai.ToolSchema;
import io.github.diodeme.ji.error.JiException;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Flow;
import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.Test;

class OpenAiProviderTest {
    @Test
    void normalizesV1ExactlyOnce() {
        assertEquals("https://example.test/v1/chat/completions", OpenAiProvider.normalizeEndpoint("https://example.test").toString());
        assertEquals("https://example.test/v1/chat/completions", OpenAiProvider.normalizeEndpoint("https://example.test/v1/").toString());
    }

    @Test
    void closedProviderUsesPublicStructuredError() {
        var provider = OpenAiProvider.builder().baseUrl("https://example.test").build();
        provider.close();
        JiException closed = assertThrows(JiException.class, () -> provider.stream(request()));
        assertEquals("provider.closed", closed.error().code().code());
        assertEquals(Map.of("provider", "openai"), closed.error().parameters());
    }

    @Test
    void cancellationAfterHeadersStopsStalledBodyAndEmitsOneAbortedTerminal() throws Exception {
        var requestArrived = new CountDownLatch(1);
        var releaseServer = new CountDownLatch(1);
        HttpServer server = HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(), 0), 0);
        server.createContext("/v1/chat/completions", exchange -> {
            exchange.getRequestBody().readAllBytes();
            exchange.getResponseHeaders().set("Content-Type", "text/event-stream");
            exchange.sendResponseHeaders(200, 0);
            exchange.getResponseBody().write("data: {\"id\":\"response-1\",\"choices\":[]}\n\n".getBytes(StandardCharsets.UTF_8));
            exchange.getResponseBody().flush();
            requestArrived.countDown();
            try {
                releaseServer.await(5, TimeUnit.SECONDS);
                exchange.getResponseBody().write("data: [DONE]\n\n".getBytes(StandardCharsets.UTF_8));
            } catch (java.io.IOException ignored) {
                // Client cancellation may close the response body before this write.
            } catch (InterruptedException exception) {
                Thread.currentThread().interrupt();
            } finally {
                exchange.close();
            }
        });
        server.start();
        var cancellation = new CancellationSource();
        try (var provider = OpenAiProvider.builder().baseUrl(
                "http://127.0.0.1:" + server.getAddress().getPort()).build()) {
            Collector collector = subscribe(provider.stream(request(cancellation)));
            assertTrue(requestArrived.await(5, TimeUnit.SECONDS));
            assertTrue(collector.awaitEvent(ModelStreamEvent.Started.class, 5, TimeUnit.SECONDS));
            assertTrue(cancellation.cancel());
            assertTrue(collector.done.await(1, TimeUnit.SECONDS), "abort did not terminate stalled stream");
            long terminals = collector.events.stream().filter(event -> event instanceof ModelStreamEvent.Completed
                    || event instanceof ModelStreamEvent.Failed).count();
            assertEquals(1, terminals);
            assertTrue(collector.events.stream().anyMatch(event -> event instanceof ModelStreamEvent.Completed completed
                    && completed.stopReason() == ModelStreamEvent.StopReason.ABORTED));
            releaseServer.countDown();
            Thread.sleep(50);
            long terminalsAfterServerRelease = collector.events.stream().filter(
                    event -> event instanceof ModelStreamEvent.Completed || event instanceof ModelStreamEvent.Failed).count();
            assertEquals(1, terminalsAfterServerRelease);
        } finally {
            releaseServer.countDown();
            server.stop(0);
        }
    }

    @Test
    void parsesUtf8SplitAcrossPublisherCallbacks() throws Exception {
        byte[] body = ("data: {\"id\":\"response-1\",\"choices\":[{\"delta\":{\"content\":\"你好\"}}]}\n\n"
                + "data: [DONE]\n").getBytes(StandardCharsets.UTF_8);
        int split = java.util.HexFormat.of().formatHex(body).indexOf("e5a5bd") / 2 + 1;
        HttpServer server = HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(), 0), 0);
        server.createContext("/v1/chat/completions", exchange -> {
            exchange.getRequestBody().readAllBytes();
            exchange.getResponseHeaders().set("Content-Type", "text/event-stream");
            exchange.sendResponseHeaders(200, 0);
            exchange.getResponseBody().write(body, 0, split);
            exchange.getResponseBody().flush();
            exchange.getResponseBody().write(body, split, body.length - split);
            exchange.close();
        });
        server.start();
        try (var provider = OpenAiProvider.builder().baseUrl("http://127.0.0.1:" + server.getAddress().getPort()).build()) {
            List<ModelStreamEvent> events = collect(provider.stream(request()));
            assertTrue(events.stream().anyMatch(event -> event instanceof ModelStreamEvent.TextDelta delta
                    && delta.text().equals("你好")));
        } finally {
            server.stop(0);
        }
    }

    private static ModelRequest request() {
        return request(new CancellationSource());
    }

    private static ModelRequest request(CancellationSource cancellation) {
        return new ModelRequest("session-1", new ModelRef("openai", "model"), "",
                List.of(new Message("message-1", Message.Role.USER,
                        List.of(new Content.Text("hello")), Instant.EPOCH)),
                List.of(), Map.of(), cancellation.token());
    }

    @Test
    void parsesNonStreamingTextToolAndUsage() throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(), 0), 0);
        server.createContext("/v1/chat/completions", exchange -> {
            String requestBody = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
            assertTrue(requestBody.contains("\"stream\":false"));
            byte[] response = ("{\"id\":\"response-2\",\"choices\":[{\"message\":{\"content\":\"done\","
                    + "\"tool_calls\":[{\"id\":\"call-2\",\"function\":{\"name\":\"echo\","
                    + "\"arguments\":\"{\\\"value\\\":\\\"y\\\"}\"}}]},\"finish_reason\":\"tool_calls\"}],"
                    + "\"usage\":{\"prompt_tokens\":3,\"completion_tokens\":2}}")
                    .getBytes(StandardCharsets.UTF_8);
            exchange.sendResponseHeaders(200, response.length);
            exchange.getResponseBody().write(response);
            exchange.close();
        });
        server.start();
        try (var provider = OpenAiProvider.builder().baseUrl(
                "http://127.0.0.1:" + server.getAddress().getPort()).build()) {
            var response = provider.complete(request()).toCompletableFuture().get(5, TimeUnit.SECONDS);
            assertEquals("response-2", response.responseId());
            assertEquals("done", ((Content.Text) response.content().getFirst()).text());
            assertTrue(response.content().stream().anyMatch(content -> content instanceof Content.ToolCall call
                    && call.arguments().equals(Map.of("value", "y"))));
            assertEquals(5, response.usage().totalTokens());
            assertEquals(ModelStreamEvent.StopReason.TOOL_USE, response.stopReason());
        } finally {
            server.stop(0);
        }
    }

    @Test
    void mapsHttpAndMalformedStreamErrorsWithoutLeakingResponseOrCredential() throws Exception {
        var hits = new java.util.concurrent.atomic.AtomicInteger();
        HttpServer server = HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(), 0), 0);
        server.createContext("/v1/chat/completions", exchange -> {
            hits.incrementAndGet();
            exchange.getRequestBody().readAllBytes();
            exchange.getResponseHeaders().set("Retry-After", "3");
            exchange.sendResponseHeaders(429, -1);
            exchange.close();
        });
        server.start();
        try (var provider = OpenAiProvider.builder().baseUrl(
                "http://127.0.0.1:" + server.getAddress().getPort())
                .credential(new io.github.diodeme.ji.ai.CredentialReference("test", io.github.diodeme.ji.ai.CredentialReference.Type.API_KEY), ignored -> java.util.concurrent.CompletableFuture.completedFuture(io.github.diodeme.ji.ai.CredentialMaterial.apiKey(io.github.diodeme.ji.ai.SensitiveValue.of("test-secret")))).build()) {
            List<ModelStreamEvent> events = collect(provider.stream(request()), 20);
            assertEquals(3, hits.get());
            assertEquals(1, events.stream().filter(ModelStreamEvent.Failed.class::isInstance).count());
            ProviderFailureView failure = events.stream().filter(ModelStreamEvent.Failed.class::isInstance)
                    .map(ModelStreamEvent.Failed.class::cast)
                    .map(value -> new ProviderFailureView(value.failure().code(), value.failure().parameters().toString()))
                    .findFirst().orElseThrow();
            assertEquals("provider.rate_limited", failure.code());
            assertFalse(failure.parameters().contains("test-secret"));
        } finally {
            server.stop(0);
        }
    }

    @Test
    void parsesTextToolUsageAndDoesNotExposeAuthorization() throws Exception {
        var captured = new java.util.concurrent.atomic.AtomicReference<String>();
        HttpServer server = HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(), 0), 0);
        server.createContext("/v1/chat/completions", exchange -> {
            captured.set(new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
            byte[] body = ("data: {\"id\":\"response-1\",\"choices\":[{\"delta\":{\"content\":\"Hi \"}}]}\n\n"
                    + "data: {\"choices\":[{\"delta\":{\"content\":\"there\",\"tool_calls\":[{\"index\":0,\"id\":\"call-1\",\"function\":{\"name\":\"echo\",\"arguments\":\"{\\\"value\\\":\\\"x\\\"}\"}}]},\"finish_reason\":\"tool_calls\"}],\"usage\":{\"prompt_tokens\":4,\"completion_tokens\":2}}\n\n"
                    + "data: [DONE]\n\n").getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().set("Content-Type", "text/event-stream");
            exchange.sendResponseHeaders(200, body.length);
            exchange.getResponseBody().write(body);
            exchange.close();
        });
        server.start();
        try (var provider = OpenAiProvider.builder().baseUrl("http://127.0.0.1:" + server.getAddress().getPort())
                .credential(new io.github.diodeme.ji.ai.CredentialReference("test", io.github.diodeme.ji.ai.CredentialReference.Type.API_KEY), ignored -> java.util.concurrent.CompletableFuture.completedFuture(io.github.diodeme.ji.ai.CredentialMaterial.apiKey(io.github.diodeme.ji.ai.SensitiveValue.of("test-secret")))).build()) {
            var request = new ModelRequest("session-1", new ModelRef("openai", "model"), "",
                    List.of(new Message("message-1", Message.Role.USER, List.of(new Content.Text("hello")), Instant.EPOCH)),
                    List.of(new ToolSchema("echo", "echo", Map.of("type", "object"))), Map.of(), new CancellationSource().token());
            List<ModelStreamEvent> events = collect(provider.stream(request));
            assertTrue(events.stream().anyMatch(event -> event instanceof ModelStreamEvent.TextDelta delta && delta.text().equals("Hi ")));
            assertTrue(events.stream().anyMatch(event -> event instanceof ModelStreamEvent.ToolCallReady ready
                    && ready.toolCall().arguments().equals(Map.of("value", "x"))));
            assertTrue(events.stream().anyMatch(event -> event instanceof ModelStreamEvent.Completed complete
                    && complete.usage().totalTokens() == 6));
            assertFalse(captured.get().contains("test-secret"));
            assertTrue(captured.get().contains("\"stream\":true"));
        } finally {
            server.stop(0);
        }
    }

    private static List<ModelStreamEvent> collect(Flow.Publisher<ModelStreamEvent> publisher) throws InterruptedException {
        return collect(publisher, 5);
    }

    private static List<ModelStreamEvent> collect(Flow.Publisher<ModelStreamEvent> publisher, long timeoutSeconds)
            throws InterruptedException {
        Collector collector = subscribe(publisher);
        assertTrue(collector.done.await(timeoutSeconds, TimeUnit.SECONDS));
        return List.copyOf(collector.events);
    }

    private static Collector subscribe(Flow.Publisher<ModelStreamEvent> publisher) {
        var collector = new Collector();
        publisher.subscribe(collector);
        return collector;
    }

    private record ProviderFailureView(String code, String parameters) {}

    private static final class Collector implements Flow.Subscriber<ModelStreamEvent> {
        private final List<ModelStreamEvent> events = java.util.Collections.synchronizedList(new ArrayList<>());
        private final CountDownLatch done = new CountDownLatch(1);
        @Override public void onSubscribe(Flow.Subscription subscription) { subscription.request(Long.MAX_VALUE); }
        @Override public void onNext(ModelStreamEvent item) { events.add(item); }
        @Override public void onError(Throwable throwable) { done.countDown(); }
        @Override public void onComplete() { done.countDown(); }
        private boolean awaitEvent(Class<? extends ModelStreamEvent> type, long timeout, TimeUnit unit)
                throws InterruptedException {
            long deadline = System.nanoTime() + unit.toNanos(timeout);
            while (System.nanoTime() < deadline) {
                synchronized (events) {
                    if (events.stream().anyMatch(type::isInstance)) return true;
                }
                Thread.onSpinWait();
            }
            return false;
        }
    }
}

