    private static final class Collector implements Flow.Subscriber<ModelStreamEvent> {
        private final List<ModelStreamEvent> events = java.util.Collections.synchronizedList(new ArrayList<>());
        private final CountDownLatch done = new CountDownLatch(1);
        @Override public void onSubscribe(Flow.Subscription subscription) { subscription.request(Long.MAX_VALUE); }
        @Override public void onNext(ModelStreamEvent item) { events.add(item); }
        @Override public void onError(Throwable throwable) { done.countDown(); }
        @Override public void onComplete() { done.countDown(); }
        private boolean awaitEvent(Class<? extends ModelStreamEvent> type, long timeout, TimeUnit unit)
                throws InterruptedException {
            long deadline = System.nanoTime() + unit.toNanos(timeout);
            while (System.nanoTime() < deadline) {
                synchronized (events) {
                    if (events.stream().anyMatch(type::isInstance)) return true;
                }
                Thread.onSpinWait();
            }
            return false;
        }
    }
